import type { Candle } from '../data'

export const SPOT_REST = 'https://data-api.binance.vision'
export const PERP_REST = 'https://fapi.binance.com'
export const SPOT_WS = 'wss://data-stream.binance.vision/stream'
export const PERP_WS = 'wss://fstream.binance.com/stream'

export type Ticker = { sym: string; price: number; open: number; chg: number; high: number; low: number; quoteVol: number }
export type Level = [price: number, qty: number]
export type Premium = { mark: number; index: number; funding: number; nextFunding: number }

async function get<T>(url: string): Promise<T> {
  const r = await fetch(url)
  if (!r.ok) throw new Error(`${r.status} ${url}`)
  return r.json() as Promise<T>
}

type Raw24h = { symbol: string; lastPrice: string; openPrice: string; priceChangePercent: string; highPrice: string; lowPrice: string; quoteVolume: string }
const toTicker = (r: Raw24h): Ticker => ({
  sym: r.symbol, price: +r.lastPrice, open: +r.openPrice, chg: +r.priceChangePercent,
  high: +r.highPrice, low: +r.lowPrice, quoteVol: +r.quoteVolume,
})

/** Today's tickers: the trading day starts at 00:00 UTC+8, so open/high/low/volume/change cover today only. */
export async function spotTickers(symbols: string[]): Promise<Record<string, Ticker>> {
  const q = encodeURIComponent(JSON.stringify(symbols))
  const rows = await get<Raw24h[]>(`${SPOT_REST}/api/v3/ticker/tradingDay?symbols=${q}&timeZone=8`)
  return Object.fromEntries(rows.map(r => [r.symbol, toTicker(r)]))
}

/** Milliseconds until the next 00:00 UTC+8. */
export function msToNextDayUTC8(now = Date.now()) {
  const day = 86_400_000, shift = 8 * 3_600_000
  return day - ((now + shift) % day)
}

export async function perpTicker(symbol: string): Promise<Ticker> {
  return toTicker(await get<Raw24h>(`${PERP_REST}/fapi/v1/ticker/24hr?symbol=${symbol}`))
}

type RawKline = [number, string, string, string, string, string, ...unknown[]]
const toCandle = (k: RawKline): Candle => ({ t: k[0], o: +k[1], h: +k[2], l: +k[3], c: +k[4], v: +k[5] })

export async function klines(symbol: string, interval: string, limit: number, perp = false): Promise<Candle[]> {
  const base = perp ? `${PERP_REST}/fapi/v1/klines` : `${SPOT_REST}/api/v3/klines`
  return (await get<RawKline[]>(`${base}?symbol=${symbol}&interval=${interval}&limit=${limit}`)).map(toCandle)
}

export async function perpDepth(symbol: string, limit = 20): Promise<{ bids: Level[]; asks: Level[] }> {
  const d = await get<{ bids: [string, string][]; asks: [string, string][] }>(`${PERP_REST}/fapi/v1/depth?symbol=${symbol}&limit=${limit}`)
  return { bids: d.bids.map(([p, q]) => [+p, +q]), asks: d.asks.map(([p, q]) => [+p, +q]) }
}

export async function spotDepth(symbol: string, limit = 20): Promise<{ bids: Level[]; asks: Level[] }> {
  const d = await get<{ bids: [string, string][]; asks: [string, string][] }>(`${SPOT_REST}/api/v3/depth?symbol=${symbol}&limit=${limit}`)
  return { bids: d.bids.map(([p, q]) => [+p, +q]), asks: d.asks.map(([p, q]) => [+p, +q]) }
}

export async function premium(symbol: string): Promise<Premium> {
  const p = await get<{ markPrice: string; indexPrice: string; lastFundingRate: string; nextFundingTime: number }>(
    `${PERP_REST}/fapi/v1/premiumIndex?symbol=${symbol}`)
  return { mark: +p.markPrice, index: +p.indexPrice, funding: +p.lastFundingRate, nextFunding: p.nextFundingTime }
}

/** Combined-stream WebSocket with backoff reconnect. Returns a closer. */
export function stream(base: string, streams: string[], onMsg: (stream: string, data: any) => void, onState?: (live: boolean) => void): () => void {
  let ws: WebSocket | null = null
  let closed = false
  let retry = 0
  let timer: ReturnType<typeof setTimeout> | undefined
  const connect = () => {
    ws = new WebSocket(`${base}?streams=${streams.join('/')}`)
    ws.onopen = () => { retry = 0; onState?.(true) }
    ws.onmessage = e => {
      try { const m = JSON.parse(e.data as string); onMsg(m.stream, m.data) } catch { /* ignore malformed frame */ }
    }
    ws.onclose = () => {
      onState?.(false)
      if (!closed) timer = setTimeout(connect, Math.min(30000, 1000 * 2 ** retry++))
    }
    ws.onerror = () => ws?.close()
  }
  connect()
  return () => { closed = true; clearTimeout(timer); ws?.close() }
}
